/**
 * @file ut_wb_vectors.h
 * @brief Types and tables of the generated known-answer vectors (ut_wb_vectors.c).
 * @ingroup noxtls_stm32wb_ut
 */

#ifndef UT_WB_VECTORS_H
#define UT_WB_VECTORS_H

#include <stdint.h>

/** AES ECB / CBC / CTR vector (mode 0 / 1 / 2). */
typedef struct {
    uint8_t mode;
    uint8_t key_len;
    const uint8_t *key;
    const uint8_t *iv;
    const uint8_t *pt;
    const uint8_t *ct;
    uint32_t len;
} ut_wb_mode_vec_t;

/** AES-GCM vector (96-bit nonce, 16-byte tag). */
typedef struct {
    uint8_t key_len;
    const uint8_t *key;
    const uint8_t *nonce;
    const uint8_t *aad;
    uint32_t aad_len;
    const uint8_t *pt;
    const uint8_t *ct;
    uint32_t len;
    const uint8_t *tag;
} ut_wb_gcm_vec_t;

/** AES-CCM vector. */
typedef struct {
    uint8_t key_len;
    const uint8_t *key;
    const uint8_t *nonce;
    uint32_t nonce_len;
    const uint8_t *aad;
    uint32_t aad_len;
    const uint8_t *pt;
    const uint8_t *ct;
    uint32_t len;
    const uint8_t *tag;
    uint32_t tag_len;
} ut_wb_ccm_vec_t;

/** P-256 scalar multiplication vector. */
typedef struct {
    const uint8_t *k;
    const uint8_t *px;
    const uint8_t *py;
    const uint8_t *rx;
    const uint8_t *ry;
} ut_wb_mul_vec_t;

/** P-256 ECDSA signing vector (fixed nonce). */
typedef struct {
    const uint8_t *d;
    const uint8_t *k;
    const uint8_t *e;
    const uint8_t *r;
    const uint8_t *s;
} ut_wb_sign_vec_t;

/** P-256 ECDSA verification vector (valid signature). */
typedef struct {
    const uint8_t *qx;
    const uint8_t *qy;
    const uint8_t *e;
    const uint8_t *r;
    const uint8_t *s;
} ut_wb_verify_vec_t;

/** Modular exponentiation vector (big-endian). */
typedef struct {
    const uint8_t *mod;
    const uint8_t *base;
    const uint8_t *exp;
    const uint8_t *res;
    uint32_t mod_len;
    uint32_t exp_len;
} ut_wb_modexp_vec_t;

extern const ut_wb_mode_vec_t k_ut_wb_modes[];
extern const uint32_t k_ut_wb_modes_count;
extern const ut_wb_gcm_vec_t k_ut_wb_gcm[];
extern const uint32_t k_ut_wb_gcm_count;
extern const ut_wb_ccm_vec_t k_ut_wb_ccm[];
extern const uint32_t k_ut_wb_ccm_count;
extern const ut_wb_mul_vec_t k_ut_wb_mul[];
extern const uint32_t k_ut_wb_mul_count;
extern const ut_wb_sign_vec_t k_ut_wb_sign[];
extern const uint32_t k_ut_wb_sign_count;
extern const ut_wb_verify_vec_t k_ut_wb_verify[];
extern const uint32_t k_ut_wb_verify_count;
extern const ut_wb_modexp_vec_t k_ut_wb_modexp[];
extern const uint32_t k_ut_wb_modexp_count;

/** Private key, public key X / Y of the P-256 signing vectors. */
extern const uint8_t p256_d[32];
extern const uint8_t p256_qx[32];
extern const uint8_t p256_qy[32];
/** Public key X with the low bit flipped (not on the curve). */
extern const uint8_t p256_bad_x[32];

#endif /* UT_WB_VECTORS_H */
